package net.civeira.phylax.features.oauth.theme.domain.gateway;

import java.util.Locale;

/**
 * Port for decorating authentication HTML pages.
 *
 * Responsibilities: - Wrap HTML fragments in a consistent page layout. - Apply localization and
 * theming based on locale and tenant.
 *
 * Design notes: - Implemented by infrastructure adapters. - Keeps HTML decoration outside
 * controllers.
 */
public interface DecoratePageGateway {

  /**
   * Builds a full HTML page for the provided inner content, applying the tenant's active theme.
   *
   * @param tenant tenant context used to resolve the active theme; null resolves the global default
   * @param title page title
   * @param innerContent HTML body content
   * @param locale locale for localization
   * @return full HTML page
   */
  String getFullPage(String tenant, String title, String innerContent, Locale locale);

  /**
   * Builds a full HTML page without tenant context (uses global default theme). Delegates to
   * {@link #getFullPage(TenantRef, String, String, Locale)} with {@code null} tenant.
   */
  default String getGenericFullPage(String title, String innerContent, Locale locale) {
    return getFullPage(null, title, innerContent, locale);
  }
}
